import ast
import sympy

def safe_eval(node):
    """
    A safe version of eval that only allows expressions that are safe in the context of sympy.

    Note: This function does not prevent arbitrary code execution, but it does prevent some potential attacks.
    """
    if isinstance(node, ast.BinOp):
        if node.op.__class__ in [ast.Add, ast.Sub]:
            return safe_eval(node.left) + safe_eval(node.right)
        elif node.op.__class__ == ast.Mult:
            return safe_eval(node.left) * safe_eval(node.right)
        elif node.op.__class__ == ast.Div:
            return safe_eval(node.left) / safe_eval(node.right)
    elif isinstance(node, ast.Num):
        return node.n
    elif isinstance(node, ast.Name):
        if node.id in ['sin', 'cos', 'tan','sinh', 'cosh', 'tanh']:
            return sympy.sympify(getattr(sympy, node.id)(safe_eval(node)))
        else:
            raise NameError(f"Identifier {node} is not a sympy function")
    elif isinstance(node, ast.Call):
        if isinstance(node.func, ast.Name) and node.func.id =='symbol':
            return sympy.sympify(node.args[0])
        else:
            raise TypeError("Unsupported function call")
    else:
        raise SyntaxError("Unsupported expression")

