def apply_primitive(env: Dict[str, Callable[[...],...]]) -> Callable[[str],...]:
    def apply_primitive_inner(expr: str) ->...:
        parts = expr.lstrip().split()
        if len(parts) == 0:
            raise Exception('empty expression')

        if parts[0] in env:
            # variable reference
            if len(parts)!= 1:
                raise Exception('too many parts')
            return env[parts[0]]()
        elif parts[0] == 'define':
            # variable definition
            if len(parts)!= 3:
                raise Exception('invalid definition')
            var, value_expr = parts[1], expr[len('define'+ var +''):].lstrip()
            env[var] = eval_in_env(env, value_expr)
            return env[var]()
        else:
            # constant literal
            raise Exception('unknown primitive')

    return apply_primitive_inner

