        self.locals.update({k: v for k, v in self.locals.items() if not k.startswith('__')})
        exec(compile(ast.Expression(value=self.locals), '<string>', 'eval'), {'__builtins__': {}}, self.locals)

        # Check if the input code is a truthy value
