def rpn_calculator(expression, environment):
    """Evaluates an arithmetic expression given as a reverse Polish notation string
    and a dictionary environment."""
    import re

    def rpn_evaluator(ops):
        """Evaluates a list of tokens in reverse Polish notation."""
        stack = []
        for token in map(str.strip, ops):
            if token in environment:
                stack.append(environment[token])
            elif token in {'+', '-', '*', '/'}:
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    if b == 0:
                        raise ZeroDivisionError
                    stack.append(a // b)
            else:
                stack.append(int(token))
        return stack[0]

    return rpn_evaluator(re.findall(r'\d+|[\+\-\*\/\(\d\)]+', expression))
