import re

def template_tokenizer(template):
    tokens = []
    token = ''
    in_string = False
    for char in template:
        if char == '"':
            in_string = not in_string
        elif char =='' and not in_string:
            if token:
                tokens.append(token)
                token = ''
        else:
            token += char
    if token:
        tokens.append(token)
    return tokens

def template_compile(tokens):
    def compile_lambda():
        nonlocal template_compile, scope
        scope = scope.copy()
        for token in tokens:
            if token == '(':
                exec(compile(f'def helper_function():"{"".join(tokens[tokens.index(token)+1:tokens.index(")")])}"', '<string>', 'exec'), scope)
            elif token in scope:
                yield scope[token]
            else:
                raise ValueError(f"undefined variable: {token}")
    return compile_lambda

def create_lambda(template):
    rules = {
        'add': 'lambda x, y: x + y',
       'sub': 'lambda x, y: x - y',
       'mul': 'lambda x, y: x * y',
        'div': 'lambda x, y: x / y',
        'eq': 'lambda x, y: x == y',
        'neq': 'lambda x, y: x!= y',
        'gt': 'lambda x, y: x > y',
        'lt': 'lambda x, y: x < y'
    }
    scope = {}
    tokens = template_tokenizer(template.replace(',', ', ').replace('(','( ').replace(')',') '))
    for i, token in enumerate(tokens):
        if token in rules:
            tokens[i] = rules[token]
    return template_compile(tokens).__next__()

