from functools import wraps

def safe_eval_code(request):
    functions = {
        'abs': abs,
        'len': len,
       'max': max,
       'min': min,
        'pow': pow,
        'range': lambda x, y, z=None: range(x, y, z) if z is not None else range(x, y),
       'sum': sum
    }

    def decorator(func):
        @wraps(func)
        def wrapper(request):
            code = request.get('code', '')
            try:
                # Use the functions dictionary to prevent common built-in functions from being used for execution
                code = code.replace('import ', '').replace('from ', '').replace('exit(', '').replace('sys.exit(', '')

                # Find and replace unsupported built-in functions and replace them with their alternatives from functions dictionary
                def replace_builtins(code):
                    for func, replacement in functions.items():
                        code = code.replace(f" {func}(", f"{replacement}(").replace(f'{func}(', f'{replacement}(')
                        code = code.replace(f".{func}(", f".{replacement}(")
                        code = code.replace("import " + func, '')
                        code = code.replace("from " + func, '')
                    return code
                code = replace_builtins(code)

                result = eval(replace_builtins(code), functions)
            except Exception as e:
                result = str(e)
            return result

        return wrapper
    return decorator


